flood_fill.brute:
old = image[sr][sc]; marked = grid of false, marked[sr][sc] = true
changed = true
while changed:   (one full sweep per round; stop when a sweep adds nothing)
    changed = false
    for each cell (r, c) not marked with image[r][c] == old:
        if some in-bounds neighbour is marked:
            marked[r][c] = true, changed = true
for each marked cell: image[r][c] = color
return image

flood_fill.optimal:
old = image[sr][sc]
if old == color: return image   (nothing would change, and painting could not mark visited)
image[sr][sc] = color, stack = [(sr, sc)]
while the stack is not empty:
    (r, c) = pop the top
    for each in-bounds neighbour (nr, nc) with image[nr][nc] == old:
        image[nr][nc] = color   (paint now: a painted pixel no longer matches old)
        push (nr, nc)
return image

number_of_islands.brute:
count = 0
for each cell (r, c) with grid[r][c] == '1':
    seen = {(r, c)}, stack = [(r, c)]   (a private visited set for this start)
    while the stack is not empty:
        (x, y) = pop the top
        for each in-bounds land neighbour not in seen: add it to seen, push it
    if (r, c) is the smallest cell in seen:   (count the island once, from its first cell)
        count += 1
return count

course_schedule.brute:
unlocks = list of lists, prerequisite -> courses that need it first
for each (course, pre) in prerequisites: append course to unlocks[pre]
for each start course:
    seen = empty set, stack = copy of unlocks[start]
    while the stack is not empty:
        cur = pop the top
        if cur == start: return false   (walked back to where we began: a cycle)
        if cur not in seen:
            add cur to seen, push every course in unlocks[cur]
return true

course_schedule.optimal:
unlocks = list of lists, prerequisite -> courses that need it first
waiting_on[course] = 0 for every course
for each (course, pre) in prerequisites:
    append course to unlocks[pre], waiting_on[course] += 1
queue = deque of every course with waiting_on == 0
taken = 0
while the queue is not empty:
    cur = pop from the front, taken += 1
    for each nxt in unlocks[cur]:
        waiting_on[nxt] -= 1
        if waiting_on[nxt] == 0: push nxt to the back   (its last prerequisite is done)
return taken == num_courses   (anything left over is stuck on a cycle)

number_of_connected_components.brute:
neighbours = list of neighbour lists built from edges
count = 0
for each start node:
    seen = {start}, stack = [start]
    while the stack is not empty:
        cur = pop the top
        for each neighbour nb of cur not in seen: add nb to seen, push nb
    if start is the smallest node in seen: count += 1   (count each component from its smallest node)
return count

network_delay_time.optimal:
neighbours = dict u -> list of (v, w)
arrival = empty dict node -> final arrival time
heap = min-heap of (time, node), holding (0, k)
while the heap is not empty:
    (time, u) = pop the smallest
    if u already in arrival: continue   (stale entry: u was settled earlier with a smaller time)
    arrival[u] = time
    for each (v, w) in neighbours[u]:
        if v not in arrival: push (time + w, v)
if fewer than n nodes have an arrival: return -1
return max of the arrival times

min_cost_to_connect_all_points.optimal:
in_tree = all false, heap = min-heap of (cost to join, point index) holding (0, 0)
total = 0, added = 0
while added < n:   (Prim's: always add the outside point closest to the tree)
    (cost, i) = pop the smallest
    if in_tree[i]: continue   (stale: i joined earlier through a cheaper edge)
    in_tree[i] = true, total += cost, added += 1
    for each point j not in the tree:
        push (manhattan distance from i to j, j)
return total

merge_intervals.optimal:
sort intervals by start
merged = [copy of the first interval]
for each (start, end) in the remaining intervals:
    last = the last interval in merged   (the running interval)
    if start <= last.end:
        last.end = max(last.end, end)   (fuse; max so a nested interval cannot shrink it)
    else:
        append [start, end] to merged
return merged

insert_interval.brute:
all_intervals = copies of intervals plus new_interval
sort all_intervals   (the wasted step: the input was already sorted)
merged = [first of all_intervals]
for each (start, end) in the rest of all_intervals:
    last = the last interval in merged
    if start <= last.end:
        last.end = max(last.end, end)
    else:
        append [start, end] to merged
return merged

insert_interval.optimal:
start, end = new_interval
result = empty list, i = 0, n = number of intervals
while i < n and intervals[i].end < start:   (phase 1: ends before the new one begins)
    append intervals[i] to result, i += 1
while i < n and intervals[i].start <= end:   (phase 2: overlaps, swallow it into [start, end])
    start = min(start, intervals[i].start)
    end = max(end, intervals[i].end)
    i += 1
append [start, end] to result
while i < n:   (phase 3: starts after the new one ends)
    append intervals[i] to result, i += 1
return result

non_overlapping_intervals.brute:
best = 0
for each mask from 0 to 2^n - 1:   (bit i of mask says whether interval i is kept)
    chosen = the intervals whose bit is set
    ok = true
    for each pair a, b in chosen:
        if a.start < b.end and b.start < a.end: ok = false   (strict: touching does not overlap)
    if ok: best = max(best, size of chosen)
return n - best

non_overlapping_intervals.optimal:
by_end = list of (end, start) for each interval, sorted   (end first, so the sort orders by end)
removed = 0, last_end = -infinity
for each (end, start) in by_end:
    if start >= last_end:
        last_end = end   (keep it: it begins after the last kept one finishes)
    else:
        removed += 1   (overlaps a kept interval that ends no later: drop this one)
return removed
